use anyhow::{bail, Context, Result};

/// Expand a port spec like "8080,443,9000-9005" into the full port list.
fn parse_ports(spec: &str) -> Result<Vec<u16>> {
    let mut ports = Vec::new();
    for s in spec.split(',') {
        let s = s.trim();
        if let Some((lo, hi)) = s.split_once('-') {
            let lo: u16 = lo
                .trim()
                .parse()
                .with_context(|| format!("invalid port {lo:?} in range {s:?}"))?;
            let hi: u16 = hi
                .trim()
                .parse()
                .with_context(|| format!("invalid port {hi:?} in range {s:?}"))?;
            if lo > hi {
                bail!("invalid range {s:?}: start {lo} > end {hi}");
            }
            ports.extend(lo..=hi);
        } else {
            let port: u16 = s
                .parse()
                .with_context(|| format!("invalid port {s:?}"))?;
            ports.push(port);
        }
    }
    Ok(ports)
}
```

